def send_webhook(url):
    """Send webhook with SSRF protection."""
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        raise ValueError("Invalid URL scheme")
    hostname = parsed.hostname or ''
    for blocked in BLOCKED_HOSTS:
